`timescale 1ns/1ps

// The grading testbench for the storage: a different width and depth,
// every address written and read back, the collision rule again, and
// a second instance at the narrow end of the supported range.
module tb;

  localparam int W = 4;
  localparam int D = 8;

  logic         clk = 1'b0;
  always #5 clk = ~clk;

  logic         we    = 1'b0;
  logic [2:0]   waddr = 3'd0;
  logic [2:0]   raddr = 3'd0;
  logic [W-1:0] wdata = '0;
  logic [W-1:0] rdata;

  fifo_mem #(.WIDTH(W), .DEPTH(D)) wide (
    .clk(clk), .we(we), .waddr(waddr), .wdata(wdata),
    .raddr(raddr), .rdata(rdata)
  );

  // The smallest depth the exercise supports, and a wider word.
  logic          we2    = 1'b0;
  logic          waddr2 = 1'b0;
  logic          raddr2 = 1'b0;
  logic [15:0]   wdata2 = '0;
  logic [15:0]   rdata2;

  fifo_mem #(.WIDTH(16), .DEPTH(2)) narrow (
    .clk(clk), .we(we2), .waddr(waddr2), .wdata(wdata2),
    .raddr(raddr2), .rdata(rdata2)
  );

  int i;
  int wrong;
  logic [W-1:0] got;
  logic [W-1:0] before_edge;
  logic [W-1:0] collide;
  logic [15:0]  small0, small1;

  initial begin
    wrong = 0;

    // Every address gets its own value: address i holds i + 1.
    for (i = 0; i < D; i = i + 1) begin
      @(negedge clk);
      we    = 1'b1;
      waddr = i[2:0];
      wdata = (i + 1);
    end
    @(negedge clk); we = 1'b0;

    // And every address reads back, one cycle after it is presented.
    for (i = 0; i < D; i = i + 1) begin
      @(negedge clk);
      raddr = i[2:0];
      @(posedge clk);
      #1;
      got = rdata;
      if (got !== ((i + 1) & 4'hF)) wrong = wrong + 1;
    end

    // Latency: a new address is presented and nothing has changed yet.
    @(negedge clk); raddr = 3'd0;
    #1; before_edge = rdata;

    // Collision, at an address in the middle.
    @(negedge clk); raddr = 3'd5; we = 1'b1; waddr = 3'd5; wdata = 4'hF;
    @(posedge clk); #1; collide = rdata;
    @(negedge clk); we = 1'b0;

    // The narrow instance, independently.
    @(negedge clk); we2 = 1'b1; waddr2 = 1'b0; wdata2 = 16'hBEEF;
    @(negedge clk);             waddr2 = 1'b1; wdata2 = 16'h1234;
    @(negedge clk); we2 = 1'b0; raddr2 = 1'b0;
    @(posedge clk); #1; small0 = rdata2;
    @(negedge clk); raddr2 = 1'b1;
    @(posedge clk); #1; small1 = rdata2;

    $display("CHECK every_address_reads_back 0 %0d AT %0d", wrong, $time);
    $display("CHECK depth_eight_last_word 8 %0d AT %0d", got, $time);
    $display("CHECK read_latency_one 8 %0d AT %0d", before_edge, $time);
    $display("CHECK old_word_on_collision 6 %0d AT %0d", collide, $time);
    $display("CHECK width_sixteen_first 48879 %0d AT %0d", small0, $time);
    $display("CHECK width_sixteen_second 4660 %0d AT %0d", small1, $time);
    $display("DONE 6");
    $finish;
  end

endmodule
